-- Spoken RP follow-ups. Never /me: the WoW client supplies its own emote.
local _, addon = ...
local texts = addon.localeData.deDE.generalTexts
texts.AGREE = { gruppe = { "Da sind wir uns ausnahmsweise einig.", "Euer Gedanke hat Hand und Fuß." }, ziel = { "%s, da stimme ich Euch zu." } }
texts.AMAZE = { gruppe = { "Das verschlägt selbst mir die Sprache.", "Bei allen Sternen, wie ist das möglich?" }, ziel = { "%s, Ihr überrascht mich wirklich." } }
texts.ANGRY = { gruppe = { "Meine Geduld hat gerade Feierabend gemacht.", "Wagt es nicht, das noch einmal zu versuchen." }, ziel = { "%s, Ihr reizt meine Geduld bis zum Äußersten." } }
texts.ATTACKTARGET = { gruppe = { "Waffen bereit! Das Ziel steht fest.", "Keine langen Reden, konzentriert Euch auf den Gegner!" }, ziel = { "Auf %s! Haltet die Reihen zusammen!" } }
texts.BARK = { gruppe = { "Wuff! Das sollte wohl deutlich genug sein.", "Manchmal versteht ein Hund mehr als ein Ratsherr." }, ziel = { "%s, ist das deutlich genug für Euch?" } }
texts.BASHFUL = { gruppe = { "Ein wenig weniger Aufmerksamkeit wäre angenehm.", "Ich bin ein Held, nicht die Hauptattraktion." }, ziel = { "%s, Ihr bringt mich noch zum Erröten." } }
texts.BECKON = { gruppe = { "Kommt näher, hier lässt sich besser reden.", "Keine Sorge, ich habe heute noch niemanden gebissen." }, ziel = { "%s, kommt doch zu uns herüber!" } }
texts.BEG = { gruppe = { "Ein kleines bisschen Hilfe würde Wunder wirken.", "Ich frage nicht gern zweimal, aber ich würde es tun." }, ziel = { "%s, habt Ihr ein wenig Erbarmen?" } }
texts.BELCH = { gruppe = { "Verzeiht. Das Essen hatte offenbar etwas zu sagen.", "Ein guter Braten führt manchmal das letzte Wort." }, ziel = { "%s, ich hoffe, Ihr nehmt es mir nicht übel." } }
texts.BITE = { gruppe = { "Nicht jede Drohung braucht eine Klinge.", "Ich habe noch Zähne und erstaunlich wenig Geduld." }, ziel = { "%s, kommt meinen Zähnen besser nicht zu nahe." } }
texts.BLEED = { gruppe = { "Ein Kratzer nur. Ein ausgesprochen hartnäckiger.", "Wer hat behauptet, Helden bluteten nicht?" }, ziel = { "%s, ein Verband wäre jetzt willkommen." } }
texts.BLINK = { gruppe = { "Habe ich das eben richtig gesehen?", "Meine Augen verlangen eine zweite Erklärung." }, ziel = { "%s, wiederholt das bitte für meine Augen." } }
texts.BLOW = { gruppe = { "Ein Kuss auf Reisen braucht Rückenwind.", "Möge die Brise ein freundliches Zeichen tragen." }, ziel = { "%s, diesen Luftkuss schicke ich Euch." } }
texts.BLUSH = { gruppe = { "Nun, das war jetzt ausgesprochen unerwartet.", "Meine Wangen verraten mich heute schneller als Worte." }, ziel = { "%s, Ihr macht mir die Antwort nicht gerade leicht." } }
texts.BOGGLE = { gruppe = { "Dafür fehlen mir gleich mehrere passende Worte.", "Mein Verstand bittet um eine kurze Pause." }, ziel = { "%s, erklärt mir bitte, was hier geschieht." } }
texts.BONK = { gruppe = { "Manchmal hilft nur ein kleiner Hinweis mit Nachdruck.", "Das war eine Lehre, keine Kriegserklärung." }, ziel = { "%s, merkt Euch diese freundliche Ermahnung." } }
texts.BORED = { gruppe = { "Würde bitte jemand das Abenteuer wieder einschalten?", "Ich habe schon spannendere Steine betrachtet." }, ziel = { "%s, habt Ihr zufällig eine bessere Idee?" } }
texts.BOUNCE = { gruppe = { "Heute hält mich kein Stuhl lange fest.", "Die Füße haben offenbar eigene Pläne." }, ziel = { "%s, kommt schon, bewegt Euch ein wenig!" } }
texts.BRB = { gruppe = { "Ein kurzer Abstecher, ich bin gleich zurück.", "Haltet den Platz frei und die Suppe warm." }, ziel = { "%s, ich bin in einem Augenblick wieder da." } }
texts.CACKLE = { gruppe = { "Ha! Die Sache wird immer unterhaltsamer.", "Ich sollte vielleicht weniger Freude daran haben." }, ziel = { "%s, das habt Ihr Euch selbst eingebrockt!" } }
texts.CALM = { gruppe = { "Ruhig. Wir gewinnen nichts durch Hast.", "Ein klarer Kopf ist eine zuverlässige Waffe." }, ziel = { "%s, atmet erst einmal durch." } }
texts.CHARGE = { gruppe = { "Vorwärts! Der Weg öffnet sich nicht von allein.", "Für die Mutigen gibt es keinen Rückwärtsgang." }, ziel = { "Mit mir, %s! Jetzt geht es los!" } }
texts.CHEW = { gruppe = { "Diese Ration verdient eine gründliche Überprüfung.", "Wer hastig kaut, verpasst den halben Geschmack." }, ziel = { "%s, wollt Ihr auch ein Stück?" } }
texts.CHICKEN = { gruppe = { "Gack! Das war eindeutig ein taktischer Rückzug.", "Man muss kein Huhn sein, um Gefahren zu erkennen." }, ziel = { "%s, gackert Ihr nur oder handelt Ihr auch?" } }
texts.CHUCKLE = { gruppe = { "Das war besser, als ich erwartet hatte.", "Ein kleines Lachen kann einen langen Tag retten." }, ziel = { "%s, Ihr versteht es, mich aufzuheitern." } }
texts.COLD = { gruppe = { "Hat jemand zufällig ein zweites Paar Socken?", "Selbst meine Gedanken bekommen langsam Frost." }, ziel = { "%s, kennt Ihr einen wärmeren Ort?" } }
texts.CONFUSED = { gruppe = { "Die Karte und die Wirklichkeit sind sich uneinig.", "Ich bin nicht verloren. Ich prüfe Alternativen." }, ziel = { "%s, könnt Ihr mir den Zusammenhang erklären?" } }
texts.CONGRATS = { gruppe = { "Das habt Ihr Euch mit harter Arbeit verdient!", "Heute dürfen wir die Erfolge zählen." }, ziel = { "%s, meinen herzlichen Glückwunsch!" } }
texts.COUGH = { gruppe = { "Dieser Staub hätte draußen bleiben dürfen.", "Verzeiht, die Luft ist heute ausgesprochen widerspenstig." }, ziel = { "%s, habt Ihr etwas Wasser für mich?" } }
texts.COWER = { gruppe = { "Vielleicht ist ein kleiner Schritt zurück klug.", "Mut und Übermut sind nicht dasselbe." }, ziel = { "%s, kommt lieber hinter diese Mauer." } }
texts.CRACK = { gruppe = { "Die Finger sind bereit. Der Rest muss folgen.", "Es wird Zeit, wieder in Bewegung zu kommen." }, ziel = { "%s, bereit für eine neue Runde?" } }
texts.CRINGE = { gruppe = { "Das hätte man eleganter lösen können.", "Ich tue einfach so, als hätte ich nichts gesehen." }, ziel = { "%s, sagt bitte, dass das nicht Euer Plan war." } }
texts.CRY = { gruppe = { "Manchmal sind Worte einfach zu klein.", "Auch Tränen dürfen ihren Weg finden." }, ziel = { "%s, verzeiht, ich brauche einen Augenblick." } }
texts.CURIOUS = { gruppe = { "Das sieht nach einer interessanten Geschichte aus.", "Ich würde gern wissen, wie das funktioniert." }, ziel = { "%s, erzählt mir mehr darüber." } }
